export function listBooks() {
  return fetch('http://localhost:8000/books')
    .then(response => response.json())
    .catch(error => console.error('Error fetching books:', error));
}

export function createBook(book) {
  return fetch('http://localhost:8000/books', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(book),
  })
    .then(response => response.json())
    .catch(error => console.error('Error creating book:', error));
}

export function updateBookStatus(id, status) {
  return fetch(`http://localhost:8000/books/${id}/status`, {
    method: 'PATCH',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ status }),
  })
    .then(response => response.json())
    .catch(error => console.error('Error updating book status:', error));
}

import { useEffect, useState } from 'react';
import { listBooks } from '../api';

export default function BookList() {
  const [books, setBooks] = useState([]);
  const [loading, setLoading] = useState(true2;
  const [error, setError] = useState(null);

  useEffect(() => {
    listBooks()
      .then(data => {
        setBooks(data);
        setLoading(false);
      })
      .catch(err => {
        setError(err.message);
        setLoading(false);
      });
  }, []);

  if (loading) return <div>Caricamento...</div>;
  if (error) return <div>Errore: {error}</div>;

  return (
    <div>
      <h2>I miei libri</h2>
      <ul>
        {books.map(book => (
          <li key={book.id}>
            <strong>{book.title}</strong> - {book.author} - {book.status}
          </li>
        ))}
      </ul>
    </div>
  );
}

import { useState } from 'react';
import { createBook } from '../api';

export default function BookForm() {
  const [title, setTitle] = useState('');
  const [author, setAuthor] = useState('');
  const [status, setStatus] = useState('reading');

  const handleSubmit = (e) => {
    e.preventDefault();
    createBook({ title, author, status })
      .then(() => {
        setTitle('');
        setAuthor('');
        setStatus('reading');

      })
      .catch(err => alert('Errore nella creazione del libro'));
  };

  return (
    <div>
      <h2>Aggiungi un libro</h2>
      <form onSubmit={handleSubmit}>
        <div>
          <label>
            Titolo:
            <input
              type="text"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              required
            />
          </label>
        </div>
        <div>
          <label>
            Autore:
            <input
              type="text"
              value={author}
              onChange={(e) => setAuthor(e.target.value)}
              required
            />
          </label>
        </div>
        <div>
          <label>
            Stato:
            <select value={status} onChange={(e) => setStatus(e.target.value)}>
              <option value="reading">In lettura</option>
              <option value="completed">Completato</option>
              <option value="to-read">Da leggere</option>
            </select>
          </label>
        </div>
        <button type="submit">Aggiungi</button>
      </form>
    </div>
  );
}

